b:if.b:template-skin:
/* Editor de Layout: caixas legíveis para as seções do tema */
body#layout {
  position: relative;
  padding: 12px;
  background: #f2ecf4;
}
body#layout .top-bar { display: flex; gap: 8px; }
body#layout #app-bar-left, body#layout #page-bar, body#layout #app-bar-actions { width: auto; }
body#layout #layout { display: flex; gap: 8px; padding: 8px 0; }
body#layout #main-section, body#layout #sidebar { width: auto; flex: 1; }
body#layout .footer-widgets { display: flex; gap: 8px; }
body#layout .footer-widgets > div { flex: 1; }
body#layout .layout-widget-description, body#layout .widget-wrap { color: #49454e; }
